import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { getData, saveData } from '../../services/localStorageService';
import { formatDate } from '../../utils/helpers';

const AdminEnquiries = () => {
  const [enquiries, setEnquiries] = useState(() => getData('enquiries'));
  const [selected, setSelected] = useState(null);
  const [search, setSearch] = useState('');

  const filtered = enquiries.filter(e =>
    e.name?.toLowerCase().includes(search.toLowerCase()) ||
    e.email?.toLowerCase().includes(search.toLowerCase()) ||
    e.destination?.toLowerCase().includes(search.toLowerCase())
  );

  const handleDelete = (id) => {
    if (!window.confirm('Delete this enquiry?')) return;
    const updated = enquiries.filter(e => e.id !== id);
    saveData('enquiries', updated);
    setEnquiries(updated);
    if (selected?.id === id) setSelected(null);
  };

  const handleMarkRead = (id) => {
    const updated = enquiries.map(e => e.id === id ? { ...e, status: 'Read' } : e);
    saveData('enquiries', updated);
    setEnquiries(updated);
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h4 style={{ fontFamily: 'Poppins', fontWeight: 800, margin: 0 }}>Enquiries</h4>
          <p style={{ color: '#888', margin: 0, fontSize: '0.9rem' }}>{enquiries.length} total | {enquiries.filter(e => e.status === 'New').length} new</p>
        </div>
        <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search enquiries..." className="form-control" style={{ width: 250, borderRadius: 10 }} />
      </div>

      <div className="row g-4">
        <div className={selected ? 'col-lg-7' : 'col-12'}>
          <div className="table-premium">
            <table className="table mb-0">
              <thead><tr><th>Name</th><th>Email</th><th>Destination</th><th>Date</th><th>Status</th><th>Actions</th></tr></thead>
              <tbody>
                {filtered.length === 0 ? (
                  <tr><td colSpan={6} className="text-center py-4" style={{ color: '#aaa' }}>No enquiries found</td></tr>
                ) : filtered.map((enq, i) => (
                  <motion.tr key={enq.id} initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: i * 0.04 }}
                    style={{ cursor: 'pointer', background: selected?.id === enq.id ? 'rgba(48,112,130,0.05)' : 'white' }}
                    onClick={() => { setSelected(enq); handleMarkRead(enq.id); }}>
                    <td style={{ fontWeight: 600, fontSize: '0.9rem' }}>{enq.name}</td>
                    <td style={{ fontSize: '0.85rem', color: '#666' }}>{enq.email}</td>
                    <td style={{ fontSize: '0.85rem' }}>{enq.destination || '-'}</td>
                    <td style={{ fontSize: '0.82rem', color: '#888' }}>{formatDate(enq.date)}</td>
                    <td>
                      <span style={{ background: enq.status === 'New' ? 'rgba(231,76,60,0.1)' : 'rgba(40,167,69,0.1)', color: enq.status === 'New' ? '#e74c3c' : '#28a745', padding: '2px 10px', borderRadius: 50, fontSize: '0.75rem', fontWeight: 700 }}>
                        {enq.status || 'New'}
                      </span>
                    </td>
                    <td onClick={e => e.stopPropagation()}>
                      <button onClick={() => handleDelete(enq.id)} className="btn btn-sm" style={{ background: 'rgba(231,76,60,0.1)', color: '#e74c3c', border: 'none', borderRadius: 6, padding: '4px 8px' }}>
                        <i className="bi bi-trash"></i>
                      </button>
                    </td>
                  </motion.tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {selected && (
          <div className="col-lg-5">
            <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }}
              style={{ background: 'white', borderRadius: 16, padding: 24, boxShadow: '0 4px 20px rgba(0,0,0,0.1)', position: 'sticky', top: 20 }}>
              <div className="d-flex justify-content-between align-items-center mb-4">
                <h6 style={{ fontFamily: 'Poppins', fontWeight: 700, margin: 0 }}>Enquiry Details</h6>
                <button onClick={() => setSelected(null)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#aaa' }}><i className="bi bi-x-lg"></i></button>
              </div>
              {[
                { label: 'Name', value: selected.name, icon: 'bi-person' },
                { label: 'Email', value: selected.email, icon: 'bi-envelope' },
                { label: 'Phone', value: selected.phone || 'Not provided', icon: 'bi-telephone' },
                { label: 'Destination', value: selected.destination || 'Not specified', icon: 'bi-geo-alt' },
                { label: 'Date', value: formatDate(selected.date), icon: 'bi-calendar3' },
              ].map((item, i) => (
                <div key={i} className="d-flex gap-3 mb-3">
                  <i className={`bi ${item.icon}`} style={{ color: '#307082', marginTop: 2 }}></i>
                  <div>
                    <div style={{ color: '#aaa', fontSize: '0.75rem' }}>{item.label}</div>
                    <div style={{ fontWeight: 600, fontSize: '0.9rem' }}>{item.value}</div>
                  </div>
                </div>
              ))}
              <div style={{ background: '#f8f9fa', borderRadius: 10, padding: 16, marginTop: 8 }}>
                <div style={{ color: '#aaa', fontSize: '0.75rem', marginBottom: 6 }}>Message</div>
                <p style={{ color: '#555', fontSize: '0.9rem', lineHeight: 1.6, margin: 0 }}>{selected.message}</p>
              </div>
              <div className="d-flex gap-2 mt-4">
                <a href={`mailto:${selected.email}`} className="btn btn-teal btn-sm flex-fill">
                  <i className="bi bi-envelope me-1"></i>Reply
                </a>
                <button onClick={() => handleDelete(selected.id)} className="btn btn-sm flex-fill" style={{ background: 'rgba(231,76,60,0.1)', color: '#e74c3c', border: 'none', borderRadius: 8 }}>
                  <i className="bi bi-trash me-1"></i>Delete
                </button>
              </div>
            </motion.div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminEnquiries;
